import unittest
from retry_policy import retry_delay


class RetryDelayTests(unittest.TestCase):
    def assert_delay(self, args, expected):
        result = retry_delay(*args)
        self.assertIs(type(result), int)
        self.assertEqual(result, expected)

    def test_calculation_and_cap_boundaries(self):
        cases = (
            ((0, 3, 100), 3),
            ((1, 3, 100), 6),
            ((2, 3, 100), 12),
            ((4, 3, 100), 48),
            ((5, 3, 100), 96),
            ((6, 3, 100), 100),
            ((0, 9, 4), 4),
            ((0, 7, 7), 7),
            ((3, 5, 39), 39),
            ((3, 5, 40), 40),
            ((3, 5, 41), 40),
            ((0, 1, 1), 1),
            ((1, 1, 1), 1),
            ((60, 3, 4000000000000000000), 3458764513820540928),
        )
        for args, expected in cases:
            with self.subTest(args=args):
                self.assert_delay(args, expected)

    def test_zero_base_or_cap(self):
        for attempt in (0, 1, 8, 10000):
            for base, cap in ((0, 0), (0, 17), (17, 0)):
                args = (attempt, base, cap)
                with self.subTest(args=args):
                    self.assert_delay(args, 0)

    def test_large_attempt_saturates(self):
        for args, expected in (
            ((10000, 1, 97), 97),
            ((10000, 7, 1000), 1000),
            ((10000, 100, 3), 3),
        ):
            with self.subTest(args=args):
                self.assert_delay(args, expected)

    def test_invalid_types_in_every_argument(self):
        invalid_values = (
            False, True, None, 0.0, 1.5, '1', 1 + 0j, [], (), {},
        )
        # Zero baselines also check validation before zero shortcuts.
        for baseline in ((2, 3, 17), (0, 0, 0)):
            for position in range(3):
                for invalid in invalid_values:
                    args = list(baseline)
                    args[position] = invalid
                    with self.subTest(
                        baseline=baseline, position=position, invalid=invalid
                    ):
                        with self.assertRaises(TypeError):
                            retry_delay(*args)

    def test_negative_values_in_every_argument(self):
        for baseline in ((2, 3, 17), (0, 0, 0)):
            for position in range(3):
                for negative in (-1, -10000):
                    args = list(baseline)
                    args[position] = negative
                    with self.subTest(args=args):
                        with self.assertRaises(ValueError):
                            retry_delay(*args)

    def test_monotonicity_and_persistent_saturation(self):
        previous = 0
        saturated = False
        for attempt in range(20):
            with self.subTest(attempt=attempt):
                result = retry_delay(attempt, 3, 100)
                self.assertIs(type(result), int)
                self.assertGreaterEqual(result, previous)
                self.assertLessEqual(result, 100)
                if saturated:
                    self.assertEqual(result, 100)
                saturated = saturated or result == 100
                previous = result
        self.assertTrue(saturated)


if __name__ == '__main__':
    unittest.main()
